import openpyxl,glob,json,re
f=glob.glob('*.xlsx')[0]
ws=openpyxl.load_workbook(f,data_only=True).worksheets[0]
T={
'plan':["وضع استراتيجية التعيين وخطة العمالة السنوية","مراجعة الاحتياجات وتحديث الهيكل التنظيمي واعتمادها","موافاة المراجعة والحسابات بموازنة خطة العمالة","رفع خطة العمالة على الأنظمة"],
'ext':["تحديد مصادر شغل الوظيفة","اختيار المرشحين وفق الخبرات المطلوبة","مقابلات الموارد البشرية (CBI)","تنظيم المقابلات الفنية","إتاحة طلب التوظيف على النظام","إعداد مذكرة المجتازين واعتمادها","ربط المرشحين بطلبات التوظيف","إرسال مذكرة التعيين المعتمدة","مراجعة البيانات على Internal Portal","استكمال البيانات الناقصة","الاستعلام في قوائم الحظر","إرسال بيانات استعلام الأقارب والخبرة","الاستعلام الطبي ونموذج 111","استلام نتيجة الفحص الطبي ومطابقتها","استلام نتيجة التحريات الأمنية","معالجة النتيجة الأمنية (قيد البحث / غير لائق)","توقيع العقد وتسليم العمل","احتساب مدد الخبرة (3 سنوات فأكثر)","إبلاغ رئيس المجموعة بانتهاء التعيين","منح الميزة / فتح الحساب","إرسال الرقم الوظيفي للمراجعة والمدفوعات","إعداد ملف المرشح ومسوغات التعيين","خطة التعيينات الربع سنوية لإدارة الدمج","إخطار إدارة الدمج ببيانات الموظف","إخطار المعرفة والتطوير بالعاملين الجدد","استخراج كارت العلاج وكارت الحضور"],
'exp':["تحديد مصادر شغل الوظيفة","تنظيم المقابلات الفنية","إتاحة طلب التوظيف على النظام","ربط المرشحين بطلبات التوظيف","مذكرة التعيين للإدارة العليا (CHRO / Deputy CEO / CEO)","إرسال مذكرة التعيين المعتمدة","مراجعة البيانات على Internal Portal","الاستعلام في قوائم الحظر","إرسال بيانات استعلام الأقارب والخبرة","الاستعلام الطبي ونموذج 111","استلام نتيجة الفحص الطبي ومطابقتها","استلام نتيجة التحريات الأمنية","معالجة النتيجة الأمنية (قيد البحث / غير لائق)","توقيع العقد وتسليم العمل","إبلاغ رئيس المجموعة بانتهاء التعيين","منح الميزة / فتح الحساب","إرسال الرقم الوظيفي للمراجعة والمدفوعات","إعداد ملف المرشح ومسوغات التعيين","خطة التعيينات الربع سنوية لإدارة الدمج","إخطار إدارة الدمج ببيانات الموظف","إخطار المعرفة والتطوير بالعاملين الجدد","استخراج كارت العلاج وكارت الحضور","إرسال البيانات المالية لتحديد الراتب","إعداد العرض الوظيفي (Job Offer)","موافقة المسئول الأول على العرض المالي","تقديم العرض المالي والتفاوض مع المرشح","مخاطبة الرقابة الإدارية / البنك المركزي","استلام نتيجة الرقابة الإدارية / البنك المركزي"]}
secs=[];cur=None
def cl(s): return re.sub(r'\s+',' ',str(s)).strip() if s is not None else None
for r in ws.iter_rows(values_only=True):
  a=r[0]
  if isinstance(a,str) and a.startswith(('أولا','ثانيا')):
    key=['plan','ext','exp'][len(secs)]
    cur={'key':key,'title':a.split('\n')[0].strip(),'note':'\n'.join(a.split('\n')[1:]).strip(),'steps':[]};secs.append(cur);continue
  if isinstance(a,int) and cur:
    i=len(cur['steps'])
    cur['steps'].append({'n':a,'title':T[cur['key']][i],'owner':cl(r[1]),'part':cl(r[2]),'action':str(r[3]).strip(),
     'time':r[4] if isinstance(r[4],(int,float)) else (str(r[4]).strip() if r[4] else None),
     'sla':r[5],'chal':str(r[6]).strip() if r[6] else None})
  if a=='اجمالي عدد الأيام' and cur: cur['sheetTotal']={'time':r[4],'sla':r[5]}
for s in secs:
  assert len(s['steps'])==len(T[s['key']]),s['key']
  print(s['key'],len(s['steps']),sum(x['sla'] or 0 for x in s['steps']),sum(x['time'] for x in s['steps'] if isinstance(x['time'],(int,float))),s.get('sheetTotal'))
  print(sorted({x['owner'] for x in s['steps']}|{x['part'] for x in s['steps']}))
json.dump(secs,open('data/recruitment-steps.json','w'),ensure_ascii=False)
